    #[allow(clippy::too_many_arguments)]
    fn create_expression(
        &mut self,
        sppf_node_id: Option<SPPFNodeId>,
        gss_node_id: GssNodeId,
        return_slot: SlotId,
        env: Option<EnvId>,
        p: i32,
        e: i32,
    ) {
        record!(self, Call, sppf_node_id, gss_node_id, return_slot);
        let left_child = sppf_node_id.map(|id| {
            let node = self.sppf_node(id);
            (id, node.left_extent())
        });
        let gss_node = self.gss_node(gss_node_id);
        let i = match left_child {
            Some((id, _)) => self.sppf_node(id).right_extent(),
            None => gss_node.index,
        };
        // If there is already a GSS node for this call, add an edge.
        if let Some(existing_gss_node_id) = self.get_gss_node_expression(i, p, e) {
            record!(self, GSSNodeFound, NonterminalId(423), i);
            self.add_edge_to_existing_gss_node(
                existing_gss_node_id,
                gss_node_id,
                left_child,
                return_slot,
                env,
            );
        } else {
            record!(self, GSSNodeNotFound, NonterminalId(423), i);
            let new_gss_node_id = self.new_gss_node(NonterminalId(423), i);
            self.add_gss_edge(new_gss_node_id, gss_node_id, sppf_node_id, return_slot, env);
            let arena = self.vec_arena;
            let (env_id, env) = self.new_env();
            env.bind(BINDING_P, p, arena);
            env.bind(BINDING_E, e, arena);
            self.add_first_descriptors(NonterminalId(423), i, new_gss_node_id, Some(env_id));
            self.add_gss_node_expression(i, p, e, new_gss_node_id);
        }
    }
