    fn parse_requires_modifier_ll1(&mut self, i: u32) -> Option<SPPFNodeId> {
        #[cfg(feature = "instrument")]
        self.ll1_call_log.push((NonterminalId(5), i));
        let matched = self
            .scanner
            .longest_match(&FIRST_SET_REQUIRES_MODIFIER, i)?;
        match matched {
            TerminalId(63) => {
                let mut j = i;
                if !(j == 0 || self.scanner.match_token(TerminalId(148), j - 1).is_none()) {
                    return None;
                }
                let right_child = {
                    let start = j;
                    let (end, node) =
                        self.match_terminal(TerminalId(63), start, SlotId(69), None)?;
                    if let Some(error_kind) = self.post_conditions(SlotId(69), start, end) {
                        self.add_failure(end, SlotId(69), None, || error_kind);
                        return None;
                    }
                    j = end;
                    node
                };
                let left_extent = self.sppf_node(right_child).left_extent();
                let current = right_child;
                Some(self.add_nonterminal_node(NonterminalNode {
                    nonterminal_id: NonterminalId(5),
                    return_slot: SlotId(69),
                    span: Span {
                        left_extent,
                        right_extent: j,
                    },
                    child: current,
                    ambiguous: false,
                }))
            }
            TerminalId(64) => {
                let mut j = i;
                if !(j == 0 || self.scanner.match_token(TerminalId(148), j - 1).is_none()) {
                    return None;
                }
                let right_child = {
                    let start = j;
                    let (end, node) =
                        self.match_terminal(TerminalId(64), start, SlotId(71), None)?;
                    if let Some(error_kind) = self.post_conditions(SlotId(71), start, end) {
                        self.add_failure(end, SlotId(71), None, || error_kind);
                        return None;
                    }
                    j = end;
                    node
                };
                let left_extent = self.sppf_node(right_child).left_extent();
                let current = right_child;
                Some(self.add_nonterminal_node(NonterminalNode {
                    nonterminal_id: NonterminalId(5),
                    return_slot: SlotId(71),
                    span: Span {
                        left_extent,
                        right_extent: j,
                    },
                    child: current,
                    ambiguous: false,
                }))
            }
            _ => unreachable!("LL(1) dispatch covers every terminal in FIRST_SET"),
        }
    }
