    fn parse_plus_47_ll1(&mut self, i: u32) -> Option<SPPFNodeId> {
        #[cfg(feature = "instrument")]
        self.ll1_call_log.push((NonterminalId(300), i));
        let mut j = i;
        let (body_node, body_end) = (self
            .match_terminal(TerminalId(32), j, SlotId(1936), None)
            .map(|(end, node)| (node, end)))?;
        j = body_end;
        let left_extent = i;
        let mut current = self.add_nonterminal_node(NonterminalNode {
            nonterminal_id: NonterminalId(300),
            return_slot: SlotId(1937),
            span: Span {
                left_extent,
                right_extent: j,
            },
            child: body_node,
            ambiguous: false,
        });
        #[allow(clippy::while_let_loop)]
        loop {
            let Some((node_0, pos_0)) = self.parse_layout_ll1(j).map(|node| {
                let end = self.sppf_node(node).right_extent();
                (node, end)
            }) else {
                break;
            };
            let Some((node_1, pos_1)) = self
                .match_terminal(TerminalId(58), pos_0, SlotId(1932), None)
                .map(|(end, node)| (node, end))
            else {
                break;
            };
            let Some((node_2, pos_2)) = self.parse_layout_ll1(pos_1).map(|node| {
                let end = self.sppf_node(node).right_extent();
                (node, end)
            }) else {
                break;
            };
            let Some((node_3, pos_3)) = self
                .match_terminal(TerminalId(32), pos_2, SlotId(1934), None)
                .map(|(end, node)| (node, end))
            else {
                break;
            };
            j = pos_3;
            current = self.create_intermediate_node_ll1(
                SlotId(1932),
                left_extent,
                pos_0,
                current,
                node_0,
            );
            current = self.create_intermediate_node_ll1(
                SlotId(1933),
                left_extent,
                pos_1,
                current,
                node_1,
            );
            current = self.create_intermediate_node_ll1(
                SlotId(1934),
                left_extent,
                pos_2,
                current,
                node_2,
            );
            current = self.create_intermediate_node_ll1(
                SlotId(1935),
                left_extent,
                pos_3,
                current,
                node_3,
            );
            current = self.add_nonterminal_node(NonterminalNode {
                nonterminal_id: NonterminalId(300),
                return_slot: SlotId(1935),
                span: Span {
                    left_extent,
                    right_extent: j,
                },
                child: current,
                ambiguous: false,
            });
        }
        Some(current)
    }
