    fn parse_opt_68_ll1(&mut self, i: u32) -> Option<SPPFNodeId> {
        #[cfg(feature = "instrument")]
        self.ll1_call_log.push((NonterminalId(303), i));
        let Some(matched) = self.scanner.longest_match(&FIRST_SET_OPT_68, i) else {
            return {
                let epsilon_node_id = self.get_or_create_epsilon_node(i);
                Some(self.add_nonterminal_node(NonterminalNode {
                    nonterminal_id: NonterminalId(303),
                    return_slot: SlotId(1949),
                    span: Span {
                        left_extent: i,
                        right_extent: i,
                    },
                    child: epsilon_node_id,
                    ambiguous: false,
                }))
            };
        };
        match matched {
            TerminalId(46) | TerminalId(45) => {
                let mut j = i;
                let right_child = {
                    let start = j;
                    let Some(node) = self.parse_plus_48_ll1(start) else {
                        self.add_failure(start, SlotId(1948), None, || {
                            GLLFailureKind::UnexpectedToken {
                                expected: FIRST_SET_PLUS_48.terminals.to_vec(),
                            }
                        });
                        return None;
                    };
                    let end = self.sppf_node(node).right_extent();
                    j = end;
                    node
                };
                let left_extent = self.sppf_node(right_child).left_extent();
                let current = right_child;
                Some(self.add_nonterminal_node(NonterminalNode {
                    nonterminal_id: NonterminalId(303),
                    return_slot: SlotId(1948),
                    span: Span {
                        left_extent,
                        right_extent: j,
                    },
                    child: current,
                    ambiguous: false,
                }))
            }
            _ => unreachable!("LL(1) dispatch covers every terminal in FIRST_SET"),
        }
    }
